You are a senior Python auditor.
Analyze the following Python code and list concrete problems (bugs, bad practices, missing tests, missing docstrings).

# BAD CODE - À réparer par ton swarm!

def calc(a,b):
return a+b # BUG: pas de doc, pas tests, style mauvais

def power(x,n):
    result=1
    for i in range(n):
        result*=x # BUG: pas d'erreur si n négatif
    return result

# Fonction cassée volontairement
def divide(a,b):
    return a/b # CRASH si b=0!

details.output_response:
import pytest
import math

from example import add_numbers, power, divide

def test_add_numbers_positive_integers():
    assert add_numbers(2, 3) == 5

def test_add_numbers_negative_integers():
    assert add_numbers(-2, -3) == -5

def test_add_numbers_mixed_integers():
    assert add_numbers(5, -3) == 2

def test_add_numbers_positive_floats():
    assert add_numbers(2.5, 3.5) == 6.0

def test_add_numbers_mixed_int_float():
    assert add_numbers(2, 3.5) == 5.5

def test_add_numbers_zero_values():
    assert add_numbers(0, 5) == 5
    assert add_numbers(5, 0) == 5
    assert add_numbers(0, 0) == 0.0

def test_add_numbers_large_numbers():
    assert add_numbers(10**18, 2 * 10**18) == 3 * 10**18
    assert add_numbers(1.23e10, 4.56e10) == pytest.approx(5.79e10)

def test_add_numbers_small_floats():
    assert add_numbers(0.00001, 0.00002) == pytest.approx(0.00003)

def test_power_positive_exponent():
    assert power(2, 3) == 8
    assert power(3.0, 2) == 9.0

def test_power_zero_exponent():
    assert power(5, 0) == 1
    assert power(0.5, 0) == 1
    assert power(-10, 0) == 1

def test_power_negative_exponent():
    assert power(2, -2) == 0.25
    assert power(4.0, -1) == 0.25
    assert power(10, -1) == 0.1

def test_power_float_base():
    assert power(2.5, 2) == 6.25
    assert power(1.5, 3) == pytest.approx(3.375)

def test_power_negative_base_even_exponent():
    assert power(-2, 2) == 4
    assert power(-3.0, 4) == 81.0

def test_power_negative_base_odd_exponent():
    assert power(-2, 3) == -8
    assert power(-1.0, 5) == -1.0

def test_power_base_one():
    assert power(1, 100) == 1
    assert power(1, -100) == 1

def test_power_base_negative_one():
    assert power(-1, 2) == 1
    assert power(-1, 3) == -1
    assert power(-1, 0) == 1

def test_power_zero_base_positive_exponent():
    assert power(0, 5) == 0
    assert power(0.0, 2) == 0.0

def test_power_zero_to_zero():
    assert power(0, 0) == 1

def test_power_large_exponent():
    assert power(2, 30) == 2**30
    assert power(1.1, 100) == pytest.approx(1.1**100)

def test_power_large_negative_exponent():
    assert power(2, -30) == pytest.approx(2**-30)

def test_power_error_zero_to_negative_power():
    with pytest.raises(ValueError, match="Cannot raise 0 to a negative power"):
        power(0, -1)
    with pytest.raises(ValueError, match="Cannot raise 0 to a negative power"):
        power(0.0, -5)

def test_power_error_exponent_is_float():
    with pytest.raises(TypeError, match="Exponent 'n' must be an integer, but received type float"):
        power(2, 1.5)
    with pytest.raises(TypeError, match="Exponent 'n' must be an integer, but received type float"):
        power(2.0, -0.5)

def test_power_error_exponent_is_string():
    with pytest.raises(TypeError, match="Exponent 'n' must be an integer, but received type str"):
        power(2, "a")

def test_power_error_exponent_is_boolean():
    with pytest.raises(TypeError, match="Exponent 'n' must be an integer, but received type bool"):
        power(2, True)
    with pytest.raises(TypeError, match="Exponent 'n' must be an integer, but received type bool"):
        power(2, False)

def test_divide_positive_integers():
    assert divide(6, 2) == 3.0

def test_divide_negative_integers():
    assert divide(-6, -2) == 3.0

def test_divide_mixed_integers():
    assert divide(6, -3) == -2.0

def test_divide_positive_floats():
    assert divide(7.5, 2.5) == 3.0

def test_divide_mixed_int_float():
    assert divide(7, 2.0) == 3.5

def test_divide_numerator_zero():
    assert divide(0, 5) == 0.0
    assert divide(0.0, -2.5) == 0.0

def test_divide_denominator_one():
    assert divide(5, 1) == 5.0
    assert divide(-10.0, 1) == -10.0

def test_divide_small_numbers():
    assert divide(0.001, 2.0) == pytest.approx(0.0005)
    assert divide(1e-10, 1e-5) == pytest.approx(1e-5)

def test_divide_negative_result():
    assert divide(10, -3) == pytest.approx(-3.3333333333333335)
    assert divide(-10, 3) == pytest.approx(-3.3333333333333335)

def test_divide_error_division_by_zero():
    with pytest.raises(ZeroDivisionError, match="Cannot divide by zero."):
        divide(5, 0)
    with pytest.raises(ZeroDivisionError, match="Cannot divide by zero."):
        divide(0.0, 0)
    with pytest.raises(ZeroDivisionError, match="Cannot divide by zero."):
        divide(-10, 0.0)

