import pytest
from example2 import divide, square

def test_divide_positive_integers():
    assert divide(6, 2) == 3.0

def test_divide_mixed_types():
    assert divide(5, 2.0) == 2.5
    assert divide(5.0, 2) == 2.5

def test_divide_negative_numbers():
    assert divide(-10, -2) == 5.0
    assert divide(10, -2) == -5.0
    assert divide(-10, 2) == -5.0

def test_divide_zero_numerator():
    assert divide(0, 5) == 0.0
    assert divide(0.0, -100) == 0.0

def test_divide_float_results():
    assert divide(5, 2) == 2.5
    assert divide(7.5, 2.5) == 3.0

def test_divide_large_numbers():
    assert divide(1_000_000, 2) == 500_000.0
    assert divide(123456789.0, 10.0) == 12345678.9

def test_divide_small_numbers():
    assert divide(0.001, 10.0) == 0.0001
    assert divide(1e-6, 2) == 0.5e-6

def test_divide_with_true():
    assert divide(True, 2) == 0.5
    assert divide(5, True) == 5.0 # True is 1

def test_divide_with_false_numerator():
    assert divide(False, 5) == 0.0 # False is 0

def test_divide_by_zero_raises_error():
    with pytest.raises(ZeroDivisionError) as excinfo:
        divide(5, 0)
    assert str(excinfo.value) == "Cannot divide by zero"

def test_divide_by_false_raises_error():
    with pytest.raises(ZeroDivisionError) as excinfo:
        divide(10, False) # False is 0
    assert str(excinfo.value) == "Cannot divide by zero"

def test_divide_by_zero_float_raises_error():
    with pytest.raises(ZeroDivisionError) as excinfo:
        divide(5.0, 0.0)
    assert str(excinfo.value) == "Cannot divide by zero"

def test_divide_type_error_numerator_string():
    with pytest.raises(TypeError) as excinfo:
        divide("text", 2)
    assert str(excinfo.value) == "Numerator 'a' must be a numeric type (int or float), got str"

def test_divide_type_error_numerator_none():
    with pytest.raises(TypeError) as excinfo:
        divide(None, 2)
    assert str(excinfo.value) == "Numerator 'a' must be a numeric type (int or float), got NoneType"

def test_divide_type_error_denominator_list():
    with pytest.raises(TypeError) as excinfo:
        divide(5, [2])
    assert str(excinfo.value) == "Denominator 'b' must be a numeric type (int or float), got list"

def test_divide_type_error_denominator_none():
    with pytest.raises(TypeError) as excinfo:
        divide(5, None)
    assert str(excinfo.value) == "Denominator 'b' must be a numeric type (int or float), got NoneType"

def test_square_positive_integer():
    assert square(2) == 4

def test_square_negative_integer():
    assert square(-3) == 9

def test_square_zero_integer():
    assert square(0) == 0

def test_square_positive_float():
    assert square(2.5) == 6.25

def test_square_negative_float():
    assert square(-2.5) == 6.25

def test_square_zero_float():
    assert square(0.0) == 0.0

def test_square_large_integer():
    assert square(1000) == 1_000_000

def test_square_large_float():
    assert square(100.0) == 10_000.0

def test_square_small_float():
    assert square(0.1) == 0.01

def test_square_with_true():
    assert square(True) == 1

def test_square_with_false():
    assert square(False) == 0

def test_square_type_error_string():
    with pytest.raises(TypeError) as excinfo:
        square("text")
    assert str(excinfo.value) == "Input 'n' must be a numeric type (int or float), got str"

def test_square_type_error_none():
    with pytest.raises(TypeError) as excinfo:
        square(None)
    assert str(excinfo.value) == "Input 'n' must be a numeric type (int or float), got NoneType"

def test_square_type_error_list():
    with pytest.raises(TypeError) as excinfo:
        square([1, 2])
    assert str(excinfo.value) == "Input 'n' must be a numeric type (int or float), got list"

def test_square_returns_int_for_int_input():
    result = square(5)
    assert isinstance(result, int)
    assert result == 25

def test_square_returns_float_for_float_input():
    result = square(5.0)
    assert isinstance(result, float)
    assert result == 25.0

