def test_add_numbers_floating_point():
    assert add_numbers(2.5, 3.5) == 6.0
    assert add_numbers(-1.5, 2.0) == 0.5
    assert add_numbers(0.1, 0.2) == 0.3

def test_add_numbers_large_numbers():
    assert add_numbers(1_000_000_000_000, 2_000_000_000_000) == 3_000_000_000_000

def test_multiply_positive_integers():
    assert multiply(2, 3) == 6

def test_multiply_negative_integers():
    assert multiply(-2, -3) == 6

def test_multiply_mixed_integers():
    assert multiply(5, -2) == -10
    assert multiply(-5, 2) == -10

def test_multiply_with_zero():
    assert multiply(0, 5) == 0
    assert multiply(5, 0) == 0
    assert multiply(0, 0) == 0

def test_multiply_with_one():
    assert multiply(1, 5) == 5
    assert multiply(5, 1) == 5
    assert multiply(-1, 5) == -5
    assert multiply(5, -1) == -5

def test_multiply_floating_point():
    assert multiply(2.5, 2.0) == 5.0
    assert multiply(-1.5, 2.0) == -3.0
    assert multiply(0.5, 0.5) == 0.25

def test_multiply_large_numbers():
    assert multiply(1_000_000_000, 2) == 2_000_000_000
    assert multiply(10**50, 10**2) == 10**52
